from itertools import product, combinations
from collections import Counter


def _route_solver(coupon_rule, minimum_duration):
    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = bit.get(data["source"], 0)
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (data["source"], initial_mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"],) + start_state]
        while queue:
            arrival, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != arrival:
                continue
            if node == data["target"] and mask == full and (
                    coupon_rule == "at_most" or remaining == 0):
                return {"arrival": arrival}
            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                duration = edge["duration"]
                outcomes = [(depart + duration, remaining)]
                if remaining:
                    discounted = max(minimum_duration,
                                     duration - edge.get("discount", 0))
                    outcomes.append((depart + discounted, remaining - 1))
                for next_time, next_remaining in outcomes:
                    if next_time > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | bit.get(next_node, 0)
                    next_state = (next_node, next_mask, next_remaining)
                    if next_time < distances.get(next_state, float("inf")):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time,) + next_state)
        return {"arrival": None}
    return solve


def _build_component_06():
    def round_ratio(numerator, denominator, mode):
        if mode == "floor":
            return numerator // denominator
        return (2 * numerator + denominator) // (2 * denominator)

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for pos, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            key = (event.get("sequence", 0), event.get("revision", 0), pos)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = round_ratio(raw * (10000 - discount), 10000, mode)
            tax = round_ratio(net * event.get("tax_bp", 0), 10000, mode)
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        choices = []
        for name in names:
            allowed = [row["version"] for row in packages[name]
                       if row["version"] not in data.get("blocked", {}).get(name, [])
                       and (name not in data.get("pins", {})
                            or row["version"] == data["pins"][name])]
            choices.append([-1] + allowed)

        best = None
        best_vector = None
        roots = data["roots"]
        for values in product(*choices):
            selected = dict(zip(names, values))
            if any(selected[name] < bounds[0] or selected[name] > bounds[1]
                   for name, bounds in roots.items() if selected[name] != -1):
                continue
            if any(selected.get(name, -1) == -1 for name in roots):
                continue
            graph = {name: [] for name in names}
            valid = True
            for name, version in selected.items():
                if version == -1:
                    continue
                row = next(row for row in packages[name] if row["version"] == version)
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    other_version = selected[other]
                    if not dep["min"] <= other_version <= dep["max"]:
                        valid = False
                        break
                    graph[name].append(other)
                if not valid:
                    break
            if not valid:
                continue

            # Installed packages must be precisely the dependency closure of roots.
            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(graph[name])
            if any((selected[name] != -1) != (name in reachable) for name in names):
                continue

            finished, active = set(), set()
            def acyclic(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not acyclic(other) for other in graph[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            if not all(acyclic(name) for name in names if selected[name] != -1):
                continue

            vector = tuple(selected[name] for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best = {name: selected[name] for name in names if selected[name] != -1}
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


def _build_component_08():
    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        jobs = [job for job in data["jobs"] if job["id"] not in blocked]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_ids = None
        best_value = None

        for chosen in combinations(jobs, k):
            ids = {job["id"] for job in chosen}
            if not mandatory <= ids:
                continue
            counts = Counter(job["group"] for job in chosen)
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            active = []
            overlap = False
            for job in sorted(chosen, key=lambda row: (row["start"], row["end"])):
                active = [end for end in active if end > job["start"]]
                active.append(job["end"])
                if len(active) > 2:
                    overlap = True
                    break
            if overlap:
                continue
            value = sum(job["value"] for job in chosen)
            ordered_ids = sorted(ids)
            if (best_ids is None or value > best_value
                    or (value == best_value and ordered_ids > best_ids)):
                best_ids, best_value = ordered_ids, value
        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


